<form method="get" class="row g-2"><input type="hidden" name="page" value="printing"><div class="col"><input class="form-control" name="print_state" placeholder="Estado" value="<?=h((string)($_GET['print_state']??''))?>"></div><div class="col"><input class="form-control" name="print_date" type="date" value="<?=h((string)($_GET['print_date']??''))?>"></div><div class="col"><input class="form-control" name="print_center" type="number" min="1" placeholder="ID posto" value="<?=h((string)($_GET['print_center']??''))?>"></div><div class="col"><input class="form-control" name="print_printer" type="number" min="1" placeholder="ID impressora" value="<?=h((string)($_GET['print_printer']??''))?>"></div><div class="col"><button class="btn btn-outline-secondary">Filtrar</button></div></form>
<?php $where=[];$args=[];if(!empty($_GET['print_state'])){$where[]='j.state=?';$args[]=(string)$_GET['print_state'];}if(!empty($_GET['print_date'])){$where[]='date(j.created_at)=?';$args[]=(string)$_GET['print_date'];}foreach(['print_center'=>'work_center_id','print_printer'=>'printer_id'] as $key=>$column)if(!empty($_GET[$key])){$where[]='j.'.$column.'=?';$args[]=(int)$_GET[$key];}$qs=$pdo->prepare('SELECT j.id,j.created_at,j.work_center_id,j.printer_id,j.state,j.attempts,j.error,j.spool_id FROM erp_print_jobs j'.($where?' WHERE '.implode(' AND ',$where):'').' ORDER BY j.created_at DESC LIMIT 100');$qs->execute($args);?>
<div class="table-responsive"><table class="table"><thead><tr><th>Trabalho / data</th><th>Posto / impressora</th><th>Estado / tentativas</th><th>Erro / spooler</th><th></th></tr></thead><tbody><?php foreach($qs->fetchAll(PDO::FETCH_ASSOC) as $j):?><tr><td><?=h($j['id'])?><br><?=h($j['created_at'])?></td><td><?=$j['work_center_id']?> / <?=$j['printer_id']?></td><td><?=h($j['state'])?> / <?=$j['attempts']?></td><td><?=h((string)$j['error'])?> <?=h((string)$j['spool_id'])?></td><td><?php if($j['state']==='pending'):?><form method="post"><?=csrf_input()?><input type="hidden" name="job_id" value="<?=h($j['id'])?>"><button class="btn btn-outline-danger" name="print_action" value="cancel">Cancelar</button></form><form method="post" class="mt-2"><?=csrf_input()?><input type="hidden" name="job_id" value="<?=h($j['id'])?>"><input class="form-control" name="printer_id" type="number" min="1" required placeholder="ID destino compatível"><button class="btn btn-outline-secondary" name="print_action" value="reroute">Transferir pendente</button></form><?php elseif(in_array($j['state'],['completed','spooler_accepted','unknown','error','cancelled'],true)):?><form method="post"><?=csrf_input()?><input type="hidden" name="job_id" value="<?=h($j['id'])?>"><input type="hidden" name="request_key" value="<?=h(bin2hex(random_bytes(16)))?>"><label><input type="checkbox" name="acknowledge" required value="1"> Confirmo nova impressão; o original pode já ter sido impresso.</label><button class="btn btn-outline-primary" name="print_action" value="reprint">Reimprimir</button></form><?php endif;?></td></tr><?php endforeach;?></tbody></table></div><form method="post"><?=csrf_input()?><button class="btn btn-outline-secondary" name="print_action" value="purge">Limpar conteúdos terminados com mais de 30 dias</button></form>
<a class="btn btn-outline-primary mt-2" href="print_submit.php">Teste de impressão autorizado</a></details></div>
